import os
import hashlib
import hmac
import unicodedata
import json
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs, unquote
import secrets
import time

# Configuration
SECRET_KEY = secrets.token_hex(32)
BASE_DIR = os.path.abspath('/srv/documents')
SESSION_STORE = {}
RATE_LIMIT = {}

def create_session(username):
    token = secrets.token_urlsafe(32)
    SESSION_STORE[token] = {
        'username': username,
        'created': time.time(),
        'expires': time.time() + 3600
    }
    return token

def validate_session(token):
    if not token or token not in SESSION_STORE:
        return None
    session = SESSION_STORE[token]
    if time.time() > session['expires']:
        del SESSION_STORE[token]
        return None
    return session

def rate_limit_check(ip, max_requests=100, window=60):
    now = time.time()
    if ip not in RATE_LIMIT:
        RATE_LIMIT[ip] = []
    RATE_LIMIT[ip] = [t for t in RATE_LIMIT[ip] if now - t < window]
    if len(RATE_LIMIT[ip]) >= max_requests:
        return False
    RATE_LIMIT[ip].append(now)
    return True

class PathValidator:
    """Multi-layer path validation to prevent directory traversal."""

    BLOCKED_PATTERNS = [
        r'\.\.',        # literal ..
        r'\.\./',      # ../ 
        r'/\.\.',      # /..
        r'\\',         # backslashes
        r'%2e',         # encoded dots
        r'%2f',         # encoded slashes
        r'%5c',         # encoded backslashes
    ]

    ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.doc', '.docx', '.md', '.csv'}

    def __init__(self, base_directory):
        self.base_dir = os.path.abspath(base_directory)

    def _check_blocked_patterns(self, path):
        """Check for known traversal patterns in raw input."""
        lower_path = path.lower()
        for pattern in self.BLOCKED_PATTERNS:
            if re.search(pattern, lower_path):
                return False
        return True

    def _check_null_bytes(self, path):
        """Reject null bytes."""
        if '\x00' in path:
            return False
        return True

    def _check_extension(self, path):
        """Verify file extension is allowed."""
        _, ext = os.path.splitext(path)
        return ext.lower() in self.ALLOWED_EXTENSIONS

    def _normalize_unicode(self, path):
        """Normalize unicode to canonical form for consistent handling."""
        # NFKC normalization for compatibility decomposition then canonical composition
        return unicodedata.normalize('NFKC', path)

    def _resolve_path(self, filename):
        """Resolve the full path and verify it's within base directory."""
        full_path = os.path.join(self.base_dir, filename)
        resolved = os.path.realpath(full_path)
        return resolved

    def validate_and_resolve(self, user_input):
        """Full validation pipeline for user-supplied file paths."""
        if not user_input or len(user_input) > 255:
            return None, "Invalid input length"

        # Step 1: Check for blocked patterns in raw input
        if not self._check_blocked_patterns(user_input):
            return None, "Blocked pattern detected"

        # Step 2: Check for null bytes
        if not self._check_null_bytes(user_input):
            return None, "Null byte detected"

        # Step 3: URL-decode the input
        decoded = unquote(user_input)

        # Step 4: Check blocked patterns again after decoding
        if not self._check_blocked_patterns(decoded):
            return None, "Blocked pattern after decode"

        # Step 5: Normalize unicode
        normalized = self._normalize_unicode(decoded)

        # Step 6: Check extension
        if not self._check_extension(normalized):
            return None, "File extension not allowed"

        # Step 7: Resolve path
        resolved = self._resolve_path(normalized)

        # Step 8: Verify resolved path is under base directory
        if not resolved.startswith(self.base_dir + os.sep) and resolved != self.base_dir:
            return None, "Path traversal detected"

        return resolved, None


class DocumentService:
    """Service for managing user documents."""

    def __init__(self):
        self.path_validator = PathValidator(BASE_DIR)
        self._access_log = []

    def _log_access(self, username, filepath, action, success):
        self._access_log.append({
            'time': time.time(),
            'user': username,
            'path': filepath,
            'action': action,
            'success': success
        })

    def get_document(self, username, filename):
        """Retrieve a document for the authenticated user."""
        resolved_path, error = self.path_validator.validate_and_resolve(filename)

        if error:
            self._log_access(username, filename, 'read', False)
            return None, error

        if not os.path.isfile(resolved_path):
            self._log_access(username, resolved_path, 'read', False)
            return None, "File not found"

        try:
            with open(resolved_path, 'r', encoding='utf-8') as f:
                content = f.read()
            self._log_access(username, resolved_path, 'read', True)
            return content, None
        except (IOError, UnicodeDecodeError) as e:
            self._log_access(username, resolved_path, 'read', False)
            return None, "Read error"

    def list_documents(self, username, subdirectory=''):
        """List documents in a subdirectory."""
        if subdirectory:
            resolved_path, error = self.path_validator.validate_and_resolve(
                subdirectory + '/.placeholder.txt'
            )
            if error:
                return None, error
            list_dir = os.path.dirname(resolved_path)
        else:
            list_dir = self.base_dir

        if not os.path.isdir(list_dir):
            return None, "Directory not found"

        try:
            entries = []
            for entry in os.listdir(list_dir):
                full = os.path.join(list_dir, entry)
                entries.append({
                    'name': entry,
                    'type': 'dir' if os.path.isdir(full) else 'file',
                    'size': os.path.getsize(full) if os.path.isfile(full) else 0
                })
            return entries, None
        except OSError:
            return None, "List error"


class RequestHandler(BaseHTTPRequestHandler):
    service = DocumentService()

    def _get_session(self):
        cookie = self.headers.get('Cookie', '')
        for part in cookie.split(';'):
            part = part.strip()
            if part.startswith('session='):
                return validate_session(part[8:])
        return None

    def _send_json(self, status, data):
        body = json.dumps(data).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)

        if not rate_limit_check(self.client_address[0]):
            self._send_json(429, {'error': 'Rate limited'})
            return

        session = self._get_session()
        if not session:
            self._send_json(401, {'error': 'Authentication required'})
            return

        username = session['username']

        if parsed.path == '/api/documents':
            subdir = params.get('dir', [''])[0]
            result, error = self.service.list_documents(username, subdir)
            if error:
                self._send_json(400, {'error': error})
            else:
                self._send_json(200, {'documents': result})

        elif parsed.path == '/api/documents/read':
            filename = params.get('name', [None])[0]
            if not filename:
                self._send_json(400, {'error': 'Missing filename'})
                return
            content, error = self.service.get_document(username, filename)
            if error:
                self._send_json(404, {'error': error})
            else:
                self._send_json(200, {'content': content})

        else:
            self._send_json(404, {'error': 'Not found'})

    def do_POST(self):
        parsed = urlparse(self.path)

        if parsed.path == '/api/auth/login':
            content_length = int(self.headers.get('Content-Length', 0))
            if content_length > 1024:
                self._send_json(400, {'error': 'Request too large'})
                return
            body = self.rfile.read(content_length)
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self._send_json(400, {'error': 'Invalid JSON'})
                return

            # Simplified auth for demo - in production use bcrypt
            username = data.get('username', '')
            password = data.get('password', '')
            if not username or not password:
                self._send_json(400, {'error': 'Missing credentials'})
                return

            # Demo: accept any non-empty credentials
            token = create_session(username)
            self._send_json(200, {'token': token})
        else:
            self._send_json(404, {'error': 'Not found'})


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    print('Server running on port 8080')
    server.serve_forever()
